def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
    }

    def parse(text):
        tokens = token_pattern.findall(text)
        values = []
        operators = []
        expecting_operand = True
        i = 0

        def apply_operator():
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                values.append(("number", int(token)))
                expecting_operand = False

            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == "(":
                    operators.append(["(", token, 1])
                    i += 1
                    expecting_operand = True
                elif i + 2 < len(tokens) and tokens[i + 1] == ":":
                    values.append(("range", token, tokens[i + 2]))
                    i += 2
                    expecting_operand = False
                else:
                    values.append(("ref", token))
                    expecting_operand = False

            elif token == "(":
                operators.append(["(", None, 0])
                expecting_operand = True

            elif token == ",":
                while isinstance(operators[-1], str):
                    apply_operator()
                operators[-1][2] += 1
                expecting_operand = True

            elif token == ")":
                while isinstance(operators[-1], str):
                    apply_operator()
                _, function_name, argument_count = operators.pop()
                if function_name is not None:
                    args = values[-argument_count:]
                    del values[-argument_count:]
                    values.append(("function", function_name, args))
                expecting_operand = False

            else:
                op = "neg" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    apply_operator()
                operators.append(op)
                expecting_operand = True

            i += 1

        while operators:
            apply_operator()
        return values[0]

    def range_items(first, second):
        col1, row1 = ord(first[0]), int(first[1:])
        col2, row2 = ord(second[0]), int(second[1:])
        for row in range(min(row1, row2), max(row1, row2) + 1):
            for col in range(min(col1, col2), max(col1, col2) + 1):
                name = chr(col) + str(row)
                if name in cells:
                    yield ("ref", name)

    def argument_items(args):
        for arg in args:
            if arg[0] == "range":
                yield from range_items(arg[1], arg[2])
            else:
                yield arg

    def is_error(value):
        return isinstance(value, str)

    state = {}
    result = {}

    def evaluate(start):
        tasks = [("cell", start)]
        stack = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    stack.append(0)
                elif state.get(name) == 1:
                    stack.append("#CYCLE!")
                elif state.get(name) == 2:
                    stack.append(result[name])
                else:
                    state[name] = 1
                    content = cells[name]
                    tasks.append(("finish_cell", name))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        stack.append(int(content))

            elif kind == "finish_cell":
                name = task[1]
                result[name] = stack[-1]
                state[name] = 2

            elif kind == "eval":
                node = task[1]
                node_type = node[0]

                if node_type == "number":
                    stack.append(node[1])
                elif node_type == "ref":
                    tasks.append(("cell", node[1]))
                elif node_type == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif node_type == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                else:
                    name, args = node[1], node[2]
                    if name == "IF":
                        tasks.append(("if_condition", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append(
                            ("aggregate_next", name, iter(argument_items(args)), None)
                        )

            elif kind == "neg":
                value = stack.pop()
                stack.append(value if is_error(value) else -value)

            elif kind == "binary_left":
                left = stack.pop()
                if is_error(left):
                    stack.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = stack.pop()
                if is_error(right):
                    stack.append(right)
                elif op == "+":
                    stack.append(left + right)
                elif op == "-":
                    stack.append(left - right)
                elif op == "*":
                    stack.append(left * right)
                elif op == "/":
                    if right == 0:
                        stack.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        stack.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    stack.append(left == right)
                elif op == "<>":
                    stack.append(left != right)
                elif op == "<":
                    stack.append(left < right)
                elif op == "<=":
                    stack.append(left <= right)
                elif op == ">":
                    stack.append(left > right)
                else:
                    stack.append(left >= right)

            elif kind == "if_condition":
                condition = stack.pop()
                if is_error(condition):
                    stack.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate_next":
                name, items, accumulated = task[1], task[2], task[3]
                item = next(items, None)
                if item is None:
                    stack.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("aggregate_value", name, items, accumulated))
                    tasks.append(("eval", item))

            elif kind == "aggregate_value":
                name, items, accumulated = task[1], task[2], task[3]
                value = stack.pop()
                if is_error(value):
                    stack.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif name == "SUM":
                        accumulated += value
                    elif name == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("aggregate_next", name, items, accumulated))

        return stack[-1]

    for name in cells:
        if state.get(name) != 2:
            evaluate(name)

    return {name: result[name] for name in cells}
